regions = [
 region("us", NY, 42.6, -76.0, 6.6,
 "Riesling on glacial lakes, Merlot by the sea, and America's oldest winery in the Hudson Valley.",
 "New York is the third- or fourth-largest US wine state by volume, depending on the year, and second only to California in grapes grown, because the Lake Erie shore is a huge Concord juice-grape belt. Wine grapes cover about 11,000 acres, with roughly 470 wineries across 11 AVAs. The Finger Lakes, with Riesling as its flagship, is the quality heart; Long Island's maritime vineyards grow Merlot, Cabernet Franc and Chardonnay; the Hudson Valley has the longest history; and the Niagara Escarpment and Lake Erie hug the Great Lakes.",
 "Grapes were planted on Manhattan by the Dutch in the 1640s and by Huguenots in Ulster County in the 1670s. The Hudson Valley had commercial vineyards by 1827 (Croton Point), and Brotherhood Winery at Washingtonville made its first commercial vintage in 1839. In the Finger Lakes, Rev. William Bostwick planted vines at Hammondsport in 1829, and the Pleasant Valley Wine Company (1860) made 'Great Western' sparkling wine that won in Paris in 1867.\n\nAfter Prohibition, labrusca and hybrid grapes ruled until Dr. Konstantin Frank, a Ukrainian-born viticulturist who arrived at Cornell's Geneva station in 1953, persuaded Charles Fournier of Gold Seal that vinifera could survive the winters if grafted onto the right rootstocks. Frank released his first vinifera vintage in 1962. Hermann J. Wiemer (1979) followed. The Farm Winery Act of 1976 let small grape growers open wineries, and their number grew from 19 in 1976 to hundreds today. Alex and Louisa Hargrave planted Long Island's first commercial vineyard in 1973.",
 "Great Lakes and the deep Finger Lakes moderate winter cold and delay spring budbreak; glacial soils (shale, limestone, gravel) dominate upstate. Long Island has sandy, well-drained glacial outwash and a maritime climate with a long growing season.",
 "Concord and Niagara for juice; Riesling, Cabernet Franc, Chardonnay, Merlot, Pinot Noir, Gewürztraminer, Lemberger (Blaufränkisch), Saperavi; hybrids such as Seyval Blanc, Vidal and Baco Noir.",
 "Dry and off-dry Riesling; ice wine; Cabernet Franc; Long Island Merlot and rosé; sparkling wine.",
 "11 AVAs; New York's Finger Lakes Riesling uses the International Riesling Foundation sweetness scale on many labels.",
 ["Finger Lakes", "Seneca Lake", "Cayuga Lake", "Long Island", "North Fork of Long Island", "The Hamptons, Long Island", "Hudson River Region", "Upper Hudson", "Niagara Escarpment", "Lake Erie", "Champlain Valley of New York"], SRC, parent=None),
 region("us", NE, 42.0, -71.8, 7.0,
 "Coastal vineyards and cold-hardy hybrids on rocky glacial soils.",
 "New England's wine is small-scale and cool-climate, made from vinifera on the warmer coastal strip (Southeastern New England) and from cold-hardy hybrids (Marquette, Frontenac, La Crescent, St. Croix) inland. Connecticut, Massachusetts and Rhode Island share six AVAs as of 2026, and Vermont's Champlain Valley was proposed in March 2026.",
 "Leif Erikson's 'Vinland' (about 1000 AD) was named for wild grapes. Sakonnet Vineyards in Rhode Island (1975) and Chicama Vineyards on Martha's Vineyard (1971) led the modern revival.",
 "Glacial till soils; maritime moderation near the coast, harsh winters inland.",
 "Chardonnay, Cabernet Franc, Riesling, Vidal, Seyval Blanc, St. Croix, Marquette, Frontenac.",
 "Crisp whites, sparkling wine, light reds.", "Federal AVAs.",
 ["Southeastern New England", "Martha's Vineyard", "Western Connecticut Highlands", "Eastern Connecticut Highlands", "Nashoba Valley"], SRC, parent=None)]

A = []
A.append(ava("Finger Lakes", FL,
 "One of the great Riesling regions outside Europe (AVA 1982), an area of more than 2 million acres around eleven long, narrow glacial lakes in upstate New York. The deepest lakes (Seneca reaches about 190 m, Cayuga about 130 m) store summer heat and release it in winter, protecting vines on the slopes from the worst cold and delaying spring budbreak until frost danger has passed. Soils are shale, limestone and glacial gravels.\n\nDr. Konstantin Frank proved at Keuka Lake in the late 1950s that vinifera could survive here, and his winery's first vintage came in 1962. Today Riesling is the signature, from bone-dry to ice wine, with tense acidity and slate-and-citrus flavours, followed by Cabernet Franc, Pinot Noir, Lemberger, Gewürztraminer, Grüner Veltliner and Saperavi. The region has more than 100 wineries.",
 sub="New York", styles=["white", "red", "sparkling", "sweet"], dom="white", grapes="Riesling, Cabernet Franc, Pinot Noir, Chardonnay, Gewürztraminer, Lemberger, Saperavi, Seyval Blanc, Vidal",
 terroir="Glacial lakes moderate temperatures; slopes of shale, limestone and gravel; cold winters with snow cover.",
 producers=["Dr. Konstantin Frank", "Hermann J. Wiemer", "Ravines", "Red Newt", "Fox Run", "Boundary Breaks", "Heart & Hands", "Bloomer Creek", "Kelby James Russell", "Nathan Kendall"],
 contains=["Seneca Lake", "Cayuga Lake"]))
A.append(ava("Seneca Lake", FL, "The largest and deepest Finger Lake gives its name to a sub-AVA (2003) with more than 50 wineries on its slopes. The lake rarely freezes, so the 'banana belt' on its southeastern shore is the warmest part of the Finger Lakes, good for Riesling, Cabernet Franc and even Merlot. Hermann J. Wiemer, Red Newt, Ravines and Fox Run are here.", sub="Finger Lakes", styles=["white", "red", "sparkling", "sweet"], dom="white", grapes="Riesling, Cabernet Franc, Pinot Noir, Gewürztraminer, Lemberger", producers=["Hermann J. Wiemer", "Ravines", "Red Newt", "Fox Run", "Boundary Breaks", "Anthony Road"]))
A.append(ava("Cayuga Lake", FL, "The first Finger Lakes sub-AVA (1988), on the slopes of the longest Finger Lake. Cayuga is deep enough to moderate the climate, though slightly cooler than Seneca; the Cayuga Wine Trail (1983) was the first organised wine trail in America. Riesling and sparkling wines lead.", sub="Finger Lakes", styles=["white", "red", "sparkling"], dom="white", grapes="Riesling, Pinot Noir, Cabernet Franc, Chardonnay, Cayuga White", producers=["Heart & Hands", "Hosmer", "Bloomer Creek", "Sheldrake Point", "Lucas"], nerd="Cayuga White, a hybrid bred at Cornell's Geneva station and released in 1972, is named for the lake."))
A.append(ava("Long Island", LI, "The AVA (2001) covering Nassau and Suffolk counties, surrounding the North Fork and Hamptons AVAs. Long Island's maritime climate gives a growing season of about 220 days, longer than upstate, and sandy glacial soils. Merlot, Cabernet Franc, Chardonnay and rosé are its strengths.", sub="New York", styles=["red", "white", "rose", "sparkling"], dom="red", grapes="Merlot, Cabernet Franc, Chardonnay, Sauvignon Blanc, Cabernet Sauvignon", contains=["North Fork of Long Island", "The Hamptons, Long Island"]))
A.append(ava("North Fork of Long Island", LI, "The northern prong (1986) of eastern Long Island, between Long Island Sound and Peconic Bay, with most of the island's vineyards and about 40 wineries. Water on three sides moderates temperatures; well-drained sandy loam suits Merlot, Cabernet Franc and Chardonnay in a fresh, Bordeaux-like style. Alex and Louisa Hargrave planted the first vineyard at Cutchogue in 1973.", sub="Long Island", styles=["red", "white", "rose"], dom="red", grapes="Merlot, Cabernet Franc, Chardonnay, Sauvignon Blanc", producers=["Paumanok", "Bedell", "Macari", "Shinn Estate", "Lieb", "Castello di Borghese"]))
A.append(ava("The Hamptons, Long Island", LI, "The southern prong (1985) of eastern Long Island, cooler and windier than the North Fork with heavier, loamy soils. Channing Daughters, Wölffer Estate and Duck Walk make Merlot, Chardonnay, sparkling wine and rosé for the summer crowd.", sub="Long Island", styles=["red", "white", "rose", "sparkling"], dom="white", grapes="Merlot, Chardonnay, Cabernet Franc", producers=["Wölffer Estate", "Channing Daughters", "Duck Walk"]))
A.append(ava("Hudson River Region", NY, "The oldest wine region in the United States still making wine (AVA 1982), along the Hudson valley north of New York City. French Huguenots planted vines in Ulster County in the 1670s, Croton Point had a commercial vineyard by 1827, and Brotherhood Winery has operated at Washingtonville since its first commercial vintage in 1839. The region pioneered hybrids after Prohibition; Benmarl, Millbrook and Whitecliff grow Chardonnay, Cabernet Franc and Seyval Blanc.", sub="New York", styles=["white", "red", "sparkling"], dom="white", grapes="Seyval Blanc, Chardonnay, Cabernet Franc, Baco Noir, Riesling", producers=["Brotherhood", "Millbrook", "Benmarl", "Whitecliff", "Fjord"], nerd="Benmarl's vineyard at Marlboro is often cited as one of the oldest continuously planted vineyards in the US, dating to the 1770s."))
A.append(ava("Upper Hudson", NY, "An AVA (2018) north of the Hudson River Region around Saratoga and Albany, defined by its colder climate, which favours cold-hardy hybrids like Marquette, Frontenac and La Crescent; about 1,500 square miles.", sub="New York", styles=["red", "white"], dom="red", grapes="Marquette, Frontenac, La Crescent, Seyval Blanc"))
A.append(ava("Niagara Escarpment", NY, "An AVA (2005) on the bench below the Niagara Escarpment in Niagara County, the US counterpart of Ontario's Niagara benchlands across the river. Lake Ontario's moderating effect and limestone-rich soils suit Riesling, Cabernet Franc and ice wine. At approval it had about 400 acres of vineyards.", sub="New York", styles=["white", "red", "sweet"], dom="white", grapes="Riesling, Cabernet Franc, Vidal, Chardonnay", producers=["Freedom Run", "Arrowhead Spring", "Leonard Oakes"]))
A.append(ava("Lake Erie", "Lake Erie", "A three-state AVA (1983) along the south shore of Lake Erie in New York, Pennsylvania and Ohio, about 2.2 million acres. The lake keeps autumn mild, and the narrow strip between lake and escarpment is the largest Concord grape-growing area in the world, supplying Welch's juice; Welch's founder Charles Welch moved his operations to Westfield, New York in 1897. Wineries also grow Riesling, Vidal and hybrids. TTB proposed a Conneaut Creek sub-AVA in Ohio in 2024.", sub="New York, Pennsylvania, Ohio", styles=["white", "red", "sweet"], dom="white", grapes="Concord, Niagara, Riesling, Vidal, Chardonnay, Catawba", producers=["Johnson Estate", "Presque Isle", "Mazza"], contains=["Grand River Valley", "Isle St. George"]))
A.append(ava("Champlain Valley of New York", NY, "A cold AVA (2016) of about 500 square miles in Clinton and Essex counties on the western shore of Lake Champlain. TTB accepted that its short season suits cold-hardy hybrids (Frontenac, La Crescent, Marquette) rather than vinifera. At approval it had six wineries. A Champlain Valley of Vermont AVA across the lake was proposed in 2026.", sub="New York", styles=["red", "white"], dom="red", grapes="Marquette, Frontenac, La Crescent"))
A.append(ava("Southeastern New England", NE, "A coastal AVA (1983) of about 2 million acres across Connecticut, Rhode Island and Massachusetts, including Cape Cod and the islands. The ocean extends the season by a few weeks compared with inland New England. Sakonnet Vineyards (now Carolyn's Sakonnet) in Little Compton, Rhode Island, petitioned for it; Westport Rivers in Massachusetts makes fine sparkling wine.", sub="Connecticut, Rhode Island, Massachusetts", styles=["white", "sparkling", "red"], dom="white", grapes="Chardonnay, Vidal, Riesling, Cabernet Franc, Pinot Noir", producers=["Westport Rivers", "Carolyn's Sakonnet", "Stonington Vineyards", "Newport Vineyards"], contains=["Martha's Vineyard"]))
A.append(ava("Martha's Vineyard", NE, "An island AVA (1985) covering Martha's Vineyard, petitioned by Chicama Vineyards, which planted the island's first vinifera in 1971. Not to be confused with Heitz's famous Martha's Vineyard Cabernet in Napa. Little commercial production remains.", sub="Southeastern New England", styles=["white", "red"], dom="white", grapes="Chardonnay, Riesling, Cabernet Sauvignon"))
A.append(ava("Western Connecticut Highlands", NE, "An upland AVA (1988) in western Connecticut's Litchfield Hills, with cold winters and a short season; Hopkins Vineyard and others grow hybrids and cool-climate vinifera.", sub="Connecticut", styles=["white", "red"], dom="white", grapes="Seyval Blanc, Vidal, Chardonnay, Cabernet Franc", producers=["Hopkins Vineyard", "Haight-Brown"]))
A.append(ava("Eastern Connecticut Highlands", NE, "An AVA (2019) of about 1,250 square miles in the hills of eastern Connecticut, with 16 vineyards (about 115 acres) and six wineries at approval.", sub="Connecticut", styles=["white", "red"], dom="white", grapes="Seyval Blanc, Cayuga White, Chardonnay, St. Croix"))
A.append(ava("Nashoba Valley", NE, "A new AVA (effective April 2026) of about 18,367 acres in Worcester County, Massachusetts, around Bolton, Harvard and Stow, an old apple-orchard area west of Boston. The soils formed in glacial till and outwash; the most common series, Paxton, is a well-drained, deep loam. TTB accepted about 1,697 growing degree days (Celsius base), placing it in Winkler Region III. At approval it had three commercial vineyards on about 16 acres, growing Albariño, Cabernet Franc, Chardonnay, Riesling and St. Croix. Nashoba Valley Winery (1978), known for fruit wines, is the best-known producer.", sub="Massachusetts", styles=["white", "red"], dom="white", grapes="Albariño, Cabernet Franc, Chardonnay, Riesling, St. Croix", producers=["Nashoba Valley Winery"], created="2026", lat=42.42, lon=-71.60))

S = []
